<script setup lang="ts">import{inject,onMounted,watch}from'vue';import{useThemeStore}from'./themeStore';import{useAppStore}from'./store';import{useSettingsStore}from'./settingsStore';import type{SettingsClient}from'../bridge/clients/SettingsClient';import QSidebarLayout from'../design-system/layouts/QSidebarLayout.vue';import QToast from'../design-system/components/QToast.vue';const theme=useThemeStore();const app=useAppStore();const settings=useSettingsStore();const client=inject<SettingsClient>('settingsClient')!;async function loadSettings(){settings.begin();try{settings.complete(await client.getSnapshot())}catch(error){settings.fail(error)}}onMounted(()=>theme.set(theme.mode));watch(()=>app.bridge,bridge=>{if(bridge==='Connected'&&settings.status==='idle')void loadSettings()},{immediate:true})</script>
<template><QSidebarLayout><router-view/></QSidebarLayout><QToast/></template>
<style src="../styles/sidebar.css"></style>
